int main(int argc,char**argv){assert(argc==4);ifstream lead(argv[1]),ker(argv[2]);ofstream out(argv[3]);assert(lead&&ker&&out);auto start=chrono::steady_clock::now();fmpq_mpoly_ctx_init(ctx,3,ORD_LEX);{int n,m;lead>>n>>m;assert(n==18&&m==18);vector<vector<Poly>>A(n,vector<Poly>(n));for(auto&r:A)for(auto&p:r)read(lead,p,2);vector<vector<Poly>>L(7,vector<Poly>(18));for(int k=0;k<7;k++){string s;int i;ker>>s>>i;assert(s=="KERNEL"&&i==k);Poly den;read(ker,den,2);for(auto&p:L[k])read(ker,p,2);}out<<"7 7\n";long terms=0;for(int i=0;i<7;i++)for(int j=0;j<7;j++){Poly z,tmp;for(int k=0;k<18;k++)if(!fmpq_mpoly_is_zero(L[i][k].p,ctx)&&!fmpq_mpoly_is_zero(A[k][11+j].p,ctx)){fmpq_mpoly_mul(tmp.p,L[i][k].p,A[k][11+j].p,ctx);fmpq_mpoly_add(z.p,z.p,tmp.p,ctx);}terms+=fmpq_mpoly_length(z.p,ctx);write(out,z,2);}out.flush();assert(out.good());cerr<<"PROJECT_PASS TERMS "<<terms<<" SEC "<<chrono::duration<double>(chrono::steady_clock::now()-start).count()<<'\n';}fmpq_mpoly_ctx_clear(ctx);flint_cleanup();}
